%[text] Loads
%clear;%clearvars -except map;
%map = loadMapdt(2,1);
load extractedEfromRed.mat
ldos_conductance_Together__Constants;
%%
%[text] Handles: Maybe out of Loop
iCr = 2 %[output:4292be4b]
isrecrop = true %[control:checkbox:9b01]{"position":[12,16]} %[output:930d8f7b]
% Vfcs = epos{ica}(1)
%%
%[text] Process: Maybe out of Loop
icas = [1 2 1 2];ica = icas(iCr);
xrng = (0:r) + xyT{iCr,1}(1);
yrng = (0:r) + xyT{iCr,1}(2);
Gfcs = map.Gfinal0T(xrng,yrng,:);
epos = linspace(V(1),V(end),77);
%%

msb = 8; nsb = 10;
tiledlayout(msb,nsb,... %[output:21844959]
    'TileSpacing','none','Padding','tight') %[output:21844959]
for iV = 1:length(epos) %[output:group:316c6fdf]
    % sp(p)
    nexttile %[output:21844959]
    Vfcs = epos(iV);
    ewiseExtract_onePannel %[output:3c3ceae0] %[output:626a5a91] %[output:64050534] %[output:26e57fa1] %[output:6a2dadd3] %[output:9fa4582e] %[output:725d1624] %[output:83ff8839] %[output:517ccddd] %[output:8c9ff4bc] %[output:4126f4ce] %[output:8a676057] %[output:9b4083a6] %[output:174a408d] %[output:1e2011ac] %[output:7e6a6765] %[output:313d2d38] %[output:77fb0b23] %[output:9cf9445d] %[output:4629d9a5] %[output:9ba60f6c] %[output:264b31d6] %[output:6f477d60] %[output:615231d7] %[output:77f330dd] %[output:11aba62e] %[output:298230fe] %[output:7d535caa] %[output:73f900be] %[output:901fb821] %[output:7ae89e3e] %[output:30e063b7] %[output:9b3ff571] %[output:8d8bf49e] %[output:461ae705] %[output:4807abe6] %[output:9b9aed04] %[output:41b5cef3] %[output:6c6d8868] %[output:930fdc43] %[output:4deb6ea4] %[output:2151a582] %[output:21bab31e] %[output:0bfce455] %[output:943fa564] %[output:22e43cb9] %[output:81d74a90] %[output:2f5257c0] %[output:3e0fbd00] %[output:3a42879e] %[output:0f574170] %[output:5e4818d6] %[output:5a101fcc] %[output:5ab28578] %[output:926f73e1] %[output:04113084] %[output:39c56119] %[output:2c429122] %[output:453b0ee4] %[output:53a86561] %[output:6860d1b8] %[output:8cdf70a7] %[output:75765926] %[output:82c06622] %[output:8d3e97ea] %[output:3ce9b12b] %[output:541db7c5] %[output:68d21061] %[output:5b743206] %[output:4735fa86] %[output:08bc1939] %[output:6e1bb406] %[output:535e5c80] %[output:0190f85f] %[output:6b97bf8b] %[output:5dc05e2b] %[output:2da71b6b] %[output:21844959]
    p = p + 1;
    if isrecrop
        xlim([1 50])
        ylim([1 50])
    end
end %[output:group:316c6fdf]
%%
nexttile %[output:3b84eb50]
xticks([]) %[output:3b84eb50]
yticks([]) %[output:3b84eb50]
nexttile %[output:3b84eb50]
views(map.Zfinal0T(xrng,yrng)) %[output:3b84eb50]
xlim([1 50]) %[output:3b84eb50]
ylim([1 50]) %[output:3b84eb50]
SoD.draw(xyT.xyDS(iCr,:),sclSoD,thtSoD,1) %[output:3b84eb50]
ax = gca;
ax.Colormap = gray; %[output:3b84eb50]
xticks([]) %[output:3b84eb50]
yticks([]) %[output:3b84eb50]
%%
f =gcf
f.Position = [1 1 947 753]

